"use client";
import { motion } from "framer-motion";
import Link from "next/link";
import { PrimaryButton } from "./Buttons";

export default function NavBar() {
    return (
        <motion.nav
            initial={{ y: -20, opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            className="fixed top-0 left-0 right-0 h-[72px] z-50 glass-nav border-b border-[#2A2F36] px-6 md:px-12"
        >
            <div className="max-w-7xl mx-auto h-full flex justify-between items-center">
                {/* Left: Logo */}
                <Link href="/" className="flex items-center gap-2 group">
                    <div className="w-[24px] h-[24px] bg-[#1A7AFF] rounded-[4px] group-hover:rotate-90 transition-transform duration-500" />
                    <span className="font-tight font-bold text-xl tracking-tighter text-white">
                        Manobala.
                    </span>
                </Link>

                {/* Right: CTA */}
                <div className="flex items-center gap-8">
                    <div className="hidden md:flex items-center gap-6 text-sm font-medium text-[#9AA3B2]">
                        <Link href="#work" className="hover:text-white transition-colors">Work</Link>
                        <Link href="#services" className="hover:text-white transition-colors">Services</Link>
                    </div>
                    <PrimaryButton href="mailto:manovenkat06@gmail.com">
                        Consultation
                    </PrimaryButton>
                </div>
            </div>
        </motion.nav>
    );
}
