"use client";
import { motion } from "framer-motion";
import { PrimaryButton, SecondaryButton } from "./Buttons";

export default function HeroBlock({ person }: { person: any }) {
    return (
        <section className="relative min-h-screen flex flex-col justify-center items-center text-center px-6 pt-[72px] overflow-hidden">

            {/* Subtle animated gradient grain (One disruptive upgrade) */}
            <div className="absolute inset-0 z-0 hero-gradient-grain opacity-50 pointer-events-none" />
            <div className="animated-grain z-0" />

            <motion.div
                initial="initial"
                animate="animate"
                className="relative z-10 flex flex-col items-center"
            >
                {/* Status Badge */}
                <motion.div
                    variants={{
                        initial: { opacity: 0, y: 12 },
                        animate: { opacity: 1, y: 0 }
                    }}
                    transition={{ duration: 0.3, ease: [0.22, 0.61, 0.36, 1] }}
                    className="px-3 py-1 border border-[#2A2F36] rounded-full bg-black/20 backdrop-blur-sm mb-8"
                >
                    <span className="text-[12px] font-bold uppercase tracking-[0.05em] text-[#7A8AA0]">
                        OPEN FOR PROJECTS
                    </span>
                </motion.div>

                {/* Headline */}
                <motion.h1
                    variants={{
                        initial: { opacity: 0, y: 12 },
                        animate: { opacity: 1, y: 0 }
                    }}
                    transition={{ duration: 0.3, delay: 0.1, ease: [0.22, 0.61, 0.36, 1] }}
                    className="font-tight text-[48px] md:text-[72px] font-bold leading-[1.05] tracking-[-0.01em] text-white max-w-[900px] mb-8"
                >
                    Crafting <span className="italic font-light opacity-80">Experiences</span>,<br />
                    One Pixel at a Time.
                </motion.h1>

                {/* Subtext */}
                <motion.p
                    variants={{
                        initial: { opacity: 0, y: 12 },
                        animate: { opacity: 1, y: 0 }
                    }}
                    transition={{ duration: 0.3, delay: 0.2, ease: [0.22, 0.61, 0.36, 1] }}
                    className="font-sans text-[18px] text-[#9AA3B2] max-w-[560px] leading-[1.6] mb-12"
                >
                    {person.summary.split('. ')[0]}. Transforming complex ideas into seamless design intent.
                </motion.p>

                {/* Buttons Stack */}
                <motion.div
                    variants={{
                        initial: { opacity: 0, y: 12 },
                        animate: { opacity: 1, y: 0 }
                    }}
                    transition={{ duration: 0.3, delay: 0.28, ease: [0.22, 0.61, 0.36, 1] }} // stagger +80ms
                    className="flex flex-col sm:flex-row items-center gap-6"
                >
                    <PrimaryButton href="#work">View Work</PrimaryButton>
                    <SecondaryButton href="#plans">See Plans</SecondaryButton>
                </motion.div>

            </motion.div>

        </section>
    );
}
