"use client";
import { motion } from "framer-motion";

export function PrimaryButton({ children, href }: { children: React.ReactNode, href?: string }) {
    return (
        <motion.a
            href={href}
            whileHover={{ y: -2, scale: 1.06, boxShadow: "0 0 20px rgba(26, 122, 255, 0.4)" }}
            transition={{ duration: 0.3, ease: [0.22, 0.61, 0.36, 1] }}
            className="px-[18px] py-[12px] bg-[#1A7AFF] text-white rounded-[10px] font-bold text-sm inline-flex items-center justify-center cursor-pointer"
        >
            {children}
        </motion.a>
    );
}

export function SecondaryButton({ children, href }: { children: React.ReactNode, href?: string }) {
    return (
        <motion.a
            href={href}
            whileHover={{ scale: 1.06, backgroundColor: "#161B22" }}
            transition={{ duration: 0.3, ease: [0.22, 0.61, 0.36, 1] }}
            className="px-[18px] py-[12px] bg-[#11161C] border border-[#2A2F36] text-white rounded-[10px] font-bold text-sm inline-flex items-center justify-center cursor-pointer"
        >
            {children}
        </motion.a>
    );
}
